const environment=window.APP_ENV || 'development';const getCurrentHost=()=>{if(window.location.hostname !=='localhost' && window.location.hostname !=='127.0.0.1'){return window.location.hostname;}return 'localhost';};const currentHost=getCurrentHost();const configs={development:{API_BASE_URL:`http://${currentHost}:8001`,WS_BASE_URL:`ws://${currentHost}:8001`,RECORDING_API_URL:`http://${currentHost}:8002`},production:{API_BASE_URL:`http://${currentHost}:8001`,WS_BASE_URL:`ws://${currentHost}:8001`,RECORDING_API_URL:`http://${currentHost}:8002`},staging:{API_BASE_URL:'https://staging-api.example.com',WS_BASE_URL:'wss://staging-api.example.com',RECORDING_API_URL:'https://staging-recording.example.com'}};const selectedConfig=configs[environment] || configs.development;const config={ENV:environment,...selectedConfig,API_ENDPOINTS:{CAMERAS:'/api/cameras',CAMERA_BY_ID:(id)=> `/api/cameras/${id}`,CAMERA_SNAPSHOT:(id)=> `/api/cameras/${id}/snapshot`,CAMERA_HEALTH:(id)=> `/api/cameras/${id}/health`,CAMERA_TEST_CONNECTION:'/api/cameras/test',CAMERA_TEST_ALL_PATHS:'/api/cameras/test-all-paths',CAMERAS_V2:'/v2/api/cameras',CAMERAS_V2_STATUS:'/v2/api/cameras/status',CAMERA_V2_BY_ID:(id)=> `/v2/api/cameras/${id}`,CAMERA_V2_STATUS:(id)=> `/v2/api/cameras/${id}/status`,CAMERA_V2_START:(id)=> `/v2/api/cameras/${id}/start`,CAMERA_V2_STOP:(id)=> `/v2/api/cameras/${id}/stop`,CAMERA_V2_RESTART:(id)=> `/v2/api/cameras/${id}/restart`,CAMERA_V2_SETTINGS:(id)=> `/v2/api/cameras/${id}/settings`,CAMERA_RECORDING_QUALITY:(id)=> `/api/cameras/${id}/recording/quality`,SYSTEM_HEALTH:'/api/system/health',PLAYBACK:'/api/v1/playback/',PLAYBACK_SEGMENTS:(cameraId)=> `/api/v1/playbook/cameras/${cameraId}/segments`,RECORDINGS:'/api/v1/recordings/',RECORDING_STATUS:(cameraId)=> `/recordings/status/${cameraId}`,RECORDING_SEGMENTS:(cameraId)=> `/recordings/${cameraId}/segments`,HEALTH:'/health'},WS_ENDPOINTS:{NOTIFICATIONS:'/ws/notifications'},FEATURES:{ENABLE_RECORDING:true,ENABLE_PLAYBACK:true,ENABLE_DETECTION:true,ENABLE_ANALYTICS:true,NEW_CAMERA_UI:true,VLC_INTEGRATION:true,MODERN_SETTINGS_MODAL:false,VLC_SHOW_PASSWORDS:false,MASK_SENSITIVE_DATA:true,WEBSOCKET_UPDATES:true,LIVE_MOTION_DETECTION:false,GLOBAL_SETTINGS:false,ADVANCED_ANALYTICS:false,BULK_OPERATIONS:false,LAZY_LOADING:true,IMAGE_OPTIMIZATION:true},TIMEOUTS:{API_REQUEST:10000,STATUS_POLLING:30000,HEALTH_CHECK:60000,THUMBNAIL_REFRESH:5000},RETRY:{MAX_ATTEMPTS:3,BACKOFF_MULTIPLIER:2,BASE_DELAY:1000}};config.buildApiUrl=(endpoint)=>{if(typeof endpoint==='function'){return(...args)=> `${config.API_BASE_URL}${endpoint(...args)}`;}return `${config.API_BASE_URL}${endpoint}`;};config.buildWsUrl=(endpoint)=>{if(typeof endpoint==='function'){return(...args)=> `${config.WS_BASE_URL}${endpoint(...args)}`;}return `${config.WS_BASE_URL}${endpoint}`;};config.buildRecordingUrl=(endpoint)=>{if(typeof endpoint==='function'){return(...args)=> `${config.RECORDING_API_URL}${endpoint(...args)}`;}return `${config.RECORDING_API_URL}${endpoint}`;};if(environment==='development'){console.log('App Configuration:',{environment:config.ENV,apiBaseUrl:config.API_BASE_URL,wsBaseUrl:config.WS_BASE_URL,recordingApiUrl:config.RECORDING_API_URL});}export default config;